-- D-20 Product Identification & Traceability: FSQM-021 and FRM-510 Production Lot Record, both DRAFT.
--
-- Three Minor findings: 2.6.1.1, 2.6.2.1, 2.8.1.8. FSQM-021 is reserved in the remediation workbook; its
-- separate SOP-2.6.2 is folded into the one program. FRM-510 is the next number above the workbook's FRM-509.
--
-- Owner's answers, 2026-09-29: lot code = last digit of year + day of year of the BAKE day (6272), as
-- SOP-2.2.3 already states; ingredients weighed from their original containers, never decanted; all
-- product to business customers, collected; the ingredient-lot cross reference is kept on PAPER on the
-- floor and entered afterwards.
--
-- The gap this closes: FRM-301 (supplier lot in) and FRM-801 (lot out) existed, but nothing recorded which
-- supplier lots went into which lot. The ops Batch Tracker / Measuring station could, but is unused and
-- generates AB-YYYYMMDD-NNN codes that are not what is printed, so it is not relied on here.
-- FRM-510 has no verifier line: the lot is reviewed at release on FRM-701.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-021', 'FRM-510')) then
    raise exception 'FSQM-021 or FRM-510 already exists.';
  end if;
  if (select count(*) from public.sop_documents
       where sop_number in ('FRM-301', 'FRM-507', 'FRM-701', 'FRM-702', 'FRM-703', 'FRM-704', 'FRM-801', 'FRM-007', 'FSQM-009', 'FSQM-014', 'FSQM-018', 'FSQM-020', 'SOP-2.2.3', 'SOP-603', 'SOP-604') and status = 'active') <> 15 then
    raise exception 'a document D-20 names is missing or not active.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-021', 'Product Identification and Traceability Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '2.6.1.1, 2.6.2.1, 2.8.1.8', true, $q${"purpose": "This program states how every material and every product is identified from the day it arrives to the day it leaves, and how any finished lot can be traced back to the supplier lots that went into it and forward to the customer who collected it.", "scope": "All raw materials, ingredients, processing aids (including the pan spray), food-contact packaging, work in progress and finished product, from receipt to dispatch. All product is sold to business customers and collected from the site; there are no retail sales.", "definitions": "Lot code: the four-digit code printed on every pack - the last digit of the year, then the day of the year on which the product was baked. Example: 6272 = 2026, day 272 (29 September).\nLot: one product baked on one day. Two products baked on the same day share the code but are different lots; the product name on the pack tells them apart.\nSupplier lot: the lot or batch code the supplier printed on the bag, box, pail or roll.\nOne step back: from a finished lot to the supplier lots that went into it. One step forward: from a finished lot to the customer who collected it.", "responsibility": "SQF Practitioner - owns this program; runs the annual trace test; reviews the Production Lot Records.\nProduction staff - weigh every ingredient from its original container; write the supplier lot of everything used, and the product's lot code, on the Production Lot Record sheet; set the coder to the bake day's code.\nWhoever enters the sheet into the Team Portal - enters it on FRM-510 within one working day and attaches a photo of the paper sheet.\nReceiver - records supplier, lot and receipt date on FRM-301.\nWhoever releases and loads product - records the lot on FRM-701 and FRM-801.", "procedure": ["Identification at every stage", "• Receipt: every delivery is logged on FRM-301 with the supplier, the material, the supplier lot and the date received. Material that arrives without a readable lot code or label is held on FRM-702 until the supplier identifies it (SQF 2.6.1.1 i, 2.6.2.1 ii).", "• Storage: every ingredient, processing aid and packaging material stays in the bag, box, pail or roll it arrived in, with the supplier's label and lot, until it is used up. A part-used bag is closed and kept in its own bag. Nothing is decanted into another container (SQF 2.6.1.1 i).", "• Production: ingredients are weighed straight from their original containers, so the supplier lot is in front of the person using it. Batter is deposited in the run it is mixed for and is never stored (SQF 2.6.1.1 i).", "• Baked product cooling on racks carries a rack card with the product and its lot code until it is wrapped (SQF 2.6.1.1 i).", "• Finished product: every pack is coded with the lot code and best-by date on the coder (SOP-603, SOP-604) and labelled to its specification on FRM-704 and to US labelling law. The label and code are checked before release on FRM-701 under FSQM-020 (SQF 2.6.1.1 ii).", "• Held, retained and rejected product is identified by its FRM-702 hold tag or FRM-703 retention entry, each carrying the lot code.", "The lot code", "• The lot code is the last digit of the year and the three-digit day of the year on which the product was BAKED, for example 6272. It is the same code written on FRM-507 for that day's oven loads.", "• When wrapping runs into the next day, the coder is set to the bake day's code, not to the day of wrapping. A product baked on day 272 is 6272 whenever it is packed.", "• One lot is one product baked on one day. If the same product is baked on two days, it is two lots.", "The Production Lot Record - the cross reference", "• For each product baked each day, a paper Production Lot Record sheet (the printed FRM-510) is filled in on the floor as the product is made (SQF 2.6.2.1 i).", "• The sheet carries the product, its lot code and the bake date, and a line for every ingredient used with the supplier lot printed on its container. If two lots of the same ingredient are used, both are written down.", "• Processing aids are listed like ingredients - in particular the pan spray, which contains soy - so that every allergen-bearing input can be traced back (SQF 2.8.1.8).", "• If rework is used, it is written on the sheet with its own original lot code, so a lot made with rework traces back through the rework to its supplier lots (SQF 2.6.2.1 iii).", "• At wrapping, the sheet records the pack date, the number of units packed and the lot of the film roll used - the film is food-contact packaging (SQF 2.6.2.1 ii).", "• The sheet is entered on FRM-510 in the Team Portal within one working day, and a photo of the paper sheet is attached to the entry. The paper sheet is kept with the batch records under SOP-2.2.3 (SQF 2.6.2.1).", "Tracing", "• One step back: from a finished lot code, FRM-510 gives every supplier lot used, and FRM-301 gives the supplier and the date each was received (SQF 2.6.2.1 i, ii).", "• One step forward: from a finished lot code, FRM-801 gives every customer who collected it, how much and when (SQF 2.6.2.1 i).", "• From a supplier lot - for example a supplier's recall or allergen notice - the FRM-510 entries that list it give every finished lot it went into, and FRM-801 gives where those lots went (SQF 2.8.1.8).", "Testing the trace", "• At least once a year, the SQF Practitioner picks a finished lot and traces it both ways from the records alone: back to every supplier lot and its receipt on FRM-301, and forward to every customer on FRM-801 (SQF 2.6.2.1 iv).", "• The test passes when every input is traced to a supplier lot and a receipt, and the quantity packed is accounted for - collected by customers, still on site, retained on FRM-703, or disposed of on FRM-702. Any gap is raised as a CAPA on FRM-007 under FSQM-009.", "• The trace test is part of the annual product recall and withdrawal test and is reviewed with it (SQF 2.6.2.1 iv).", "Records", "• FRM-301, FRM-510, FRM-507, FRM-701 and FRM-801 are the trace records. They are kept for at least two years, as SOP-2.2.3 requires (SQF 2.6.2.1)."], "form_references": "FRM-510 - Production Lot Record\nFRM-301 - Incoming Material Receiving & Inspection Log\nFRM-507 - CCP 1 Baking Monitoring Record\nFRM-701 - Finished Product Release Record\nFRM-801 - Dispatch and Vehicle Loading Record\nFRM-702 - Non-Conforming Material Hold & Tagging Record\nFRM-703 - Retention Sample Log\nFRM-704 - Finished Product Specification\nFRM-007 - Corrective & Preventive Action (CAPA) Report", "records": "• FRM-510 entries, one per product per bake day, each with a photo of the paper sheet; the paper sheets filed with the batch records\n• FRM-301 receiving entries\n• FRM-507, FRM-701 and FRM-801 entries carrying the lot code\n• The annual trace test", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.6.1.1 (Product Identification), 2.6.2.1 (Product Trace), 2.8.1.8 (allergen traceback).\n\nSOP-2.2.3 Document and Record Control Program - the lot code and the retention of batch records.\nSOP-603, SOP-604 - the coders.\nFSQM-020 Product Release Program and FRM-701 - the label and code check before release.\nFSQM-014 Product Sampling, Inspection and Analysis Program - the receiving label scan.\nFSQM-018 Non-Conforming Product and Equipment - held product.\nFSQM-009 CAPA Program.", "revision_history": "New - 2026-09-29 - DRAFT under D-20, for the three Minor findings against 2.6.1.1, 2.6.2.1 and 2.8.1.8. Written as one program; the workbook's separate SOP-2.6.2 is not needed.\n\nWHAT THE SITE DOES (owner, 2026-09-29): the lot code is the last digit of the year and the day of the year, e.g. 6272, as SOP-2.2.3 already states; it is the BAKE day. Ingredients are weighed out of the bags and containers they arrived in; nothing is decanted. All product goes to business customers and is collected. Supplier lots are recorded at receipt on FRM-301 and the lot and customer at dispatch on FRM-801.\n\nNEW WITH THIS PROGRAM: the Production Lot Record - a paper sheet on the floor, entered afterwards on FRM-510 with a photo attached - which is the cross reference between the supplier lots used and our lot code. Before this, nothing recorded which supplier lots went into which lot. Also new: the coder is set to the bake day when wrapping runs into the next day, and the annual trace test.\n\nTHE TRACE TEST'S RECORD arrives with the recall and withdrawal program (D-21), as 2.6.2.1 iv ties the two together; the 'traceability test' row on the verification schedule stays planned until then.\n\nTO CONFIRM BEFORE ISSUE: (1) the rack card for baked product cooling on racks - product and lot code; (2) how syrup made ahead is identified while stored - open under D-14; (3) whether the coder is set to the bake day today when wrapping runs over, or whether that is new practice."}$q$::jsonb),
  ('FRM-510', 'Production Lot Record', 'form', 'Production', 'draft', 'New',
   '2.6.1.1, 2.6.2.1, 2.8.1.8', true, jsonb_build_object('form_schema', $b${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": false, "instanceTitleTemplate": "{lot_code} - {product}"}, "sections": [{"id": "lot", "title": "1. The lot", "fields": [{"id": "how_this_works", "type": "info", "label": "One entry per product per bake day", "text": "Copy the paper sheet from the floor, within one working day, and attach a photo of it. Every ingredient, the pan spray and any rework go in the table with the lot printed on its container."}, {"id": "product", "type": "text", "label": "Product", "width": "third", "required": true, "showInList": true}, {"id": "lot_code", "type": "text", "label": "Lot code", "width": "third", "required": true, "showInList": true, "help": "Year digit + bake day, e.g. 6272"}, {"id": "bake_date", "type": "date", "label": "Bake date", "width": "third", "required": true, "showInList": true}]}, {"id": "inputs", "title": "2. What went in", "fields": [{"id": "ingredients", "type": "grid", "label": "Ingredients and processing aids used", "required": true, "help": "One line per supplier lot. If two lots of the same ingredient were used, write two lines. Include the pan spray.", "scanLabel": true, "columns": [{"id": "ingredient", "label": "Ingredient", "type": "text", "required": true, "width": 2}, {"id": "brand", "label": "Brand / supplier", "type": "text", "width": 1.5}, {"id": "supplier_lot", "label": "Lot on the container", "type": "text", "required": true, "width": 1.5}, {"id": "notes", "label": "Notes", "type": "text", "width": 1.5}], "rows": {"mode": "dynamic", "min": 1}}, {"id": "rework", "type": "select", "label": "Rework", "required": true, "options": ["No rework used", "Rework used - listed in the table with its original lot code"]}]}, {"id": "packing", "title": "3. Packing", "fields": [{"id": "pack_date", "type": "date", "label": "Packed on", "width": "third", "required": true, "help": "If packing ran over two days, the first day - note the second below"}, {"id": "units_packed", "type": "text", "label": "Units packed", "width": "third", "required": true}, {"id": "film_lot", "type": "text", "label": "Film roll lot", "width": "third", "required": true}, {"id": "code_check", "type": "select", "label": "Code on the pack", "required": true, "options": ["Matches the lot code above", "Did not match - held on FRM-702"]}, {"id": "packing_notes", "type": "textarea", "label": "Notes"}]}, {"id": "sign", "title": "4. Sign-off", "fields": [{"id": "paper_photo", "type": "select", "label": "Paper sheet", "required": true, "options": ["Photo attached to this entry"]}, {"id": "recorded_by", "type": "signature", "label": "Entered by", "role": "filler", "required": true, "statement": "This entry matches the paper sheet from the floor."}]}]}$b$::jsonb));

do $verify$
declare p jsonb; fs jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-021';
  if jsonb_array_length(p) <> 28 then
    raise exception 'FSQM-021 procedure is % lines, expected 28.', jsonb_array_length(p);
  end if;
  if (select count(*) from unnest(array['2.6.1.1 i', '2.6.1.1 ii', '2.6.2.1 i', '2.6.2.1 ii', '2.6.2.1 iii', '2.6.2.1 iv', '2.8.1.8']) c where p::text like '%' || c || '%') <> 7 then
    raise exception 'FSQM-021 does not cite every limb of 2.6.1.1, 2.6.2.1 and 2.8.1.8.';
  end if;
  select content->'form_schema' into fs from public.sop_documents where sop_number = 'FRM-510';
  if (select count(*) from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') f
       where f->>'id' in ('lot_code', 'ingredients', 'film_lot')) <> 3 then
    raise exception 'FRM-510 is missing its lot, ingredient or film field.';
  end if;
end $verify$;

commit;
